        colored=[(r,c) for r,c in cells if grid[r][c] not in (0,8)]
        if not colored: continue
        r0=min(r for r,c in colored); r1=max(r for r,c in colored); c0=min(c for r,c in colored); c1=max(c for r,c in colored)
        ph=r1-r0+1; pw=c1-c0+1
        pat=[[grid[r0+u][c0+v] for v in range(pw)] for u in range(ph)]
